new_fn='''import{protectedArtifactInputHashedV1,visitProtectedArtifactInputDirectoriesV1,type ProtectedArtifactInputHashModeV1}from"./🧮️read-plan/🟦️.ts";
const protectedArtifactInputRecordedV1=new WeakMap<object,bigint>();
async function verifyProtectedArtifactInputFilesV1(root:ArtifactRelativeDirectoryV1,batch:ProtectedArtifactInputManifestV1,directories:ReadonlyMap<string,string>,files:Map<string,string>,check:()=>void,control:ResourceLeaseControl,record:boolean,fresh=false,rootIndex?:number,hash?:ProtectedArtifactInputHashModeV1):Promise<void>{
 if(rootIndex!==undefined&&(!Number.isSafeInteger(rootIndex)||rootIndex<0||rootIndex>=batch.roots.length))throw Error("Exact issued fresh input root index required");
 const limits=nativeProtectedArtifactInputProtocolV1(),closed=record||fresh,rosters=new Map<string,Set<string>>(),stamps=new Map<string,string>(),mode:ProtectedArtifactInputHashModeV1=hash??(record||fresh&&rootIndex===undefined?"all":rootIndex!==undefined?"root":"changed"),startedAtNs=BigInt(Date.now())*1000000n,recordedAtNs=protectedArtifactInputRecordedV1.get(directories),groups=new Map<string,ProtectedArtifactInputManifestV1["files"][number][]>();let quiet=0;
 if(closed){for(const path of directories.keys())rosters.set(path,new Set());for(const path of directories.keys()){const separator=path.lastIndexOf("/");rosters.get(path.slice(0,separator))?.add(path.slice(separator+1));}for(const input of batch.files){const path=batch.roots[input.root]!+"/"+input.path,separator=path.lastIndexOf("/"),parent=rosters.get(path.slice(0,separator));if(!parent)throw Error("Complete staged input directory hierarchy required");parent.add(path.slice(separator+1));}}
 await visitProtectedArtifactInputDirectoriesV1(root,directories.keys(),async(path,directory)=>{check();if(protectedArtifactInputAnchorV1(directory.stat())!==directories.get(path))throw Error("Exact staged input directory anchor changed");if(closed&&(rootIndex===undefined||path===batch.roots[rootIndex]||path.startsWith(batch.roots[rootIndex]!+"/"))){const names=await directory.names(),wanted=rosters.get(path)!;if(names.length!==wanted.size||names.some(name=>!wanted.has(name)))throw Error("Exact complete fresh immutable input roster required");stamps.set(path,protectedArtifactInputStampV1(directory.stat()));}});
 for(const input of batch.files){const path=batch.roots[input.root]!+"/"+input.path,parent=path.slice(0,path.lastIndexOf("/"));let group=groups.get(parent);if(!group){group=[];groups.set(parent,group);}group.push(input);}
 await visitProtectedArtifactInputDirectoriesV1(root,groups.keys(),async(parent,directory)=>{for(const input of groups.get(parent)!){check();const path=batch.roots[input.root]!+"/"+input.path,name=path.slice(path.lastIndexOf("/")+1),entry=await directory.entry(name);check();if(!entry||entry.kind!=="file"||entry.nlink!==1n||entry.size!==BigInt(input.bytes)||entry.dev!==root.stat().dev||!record&&files.get(path)!==protectedArtifactInputStampV1(entry))throw Error("Exact staged immutable input file required");const before=protectedArtifactInputStampV1(entry);
  if(protectedArtifactInputHashedV1(mode,input,rootIndex,entry,recordedAtNs)){await directory.withFile(name,async file=>{if(protectedArtifactInputStampV1(file.stat())!==before)throw Error("Actual immutable input read descriptor changed");const hash=artifactRetirementHashV1("sha256"),buffer=Buffer.alloc(limits.chunkBytes);let offset=0;while(offset<input.bytes){check();const count=file.read(buffer,0,Math.min(buffer.length,input.bytes-offset),offset);check();if(!count)throw Error("Complete staged input read extent required");offset+=count;hash.update(buffer.subarray(0,count));await control.publish({resource:"native-artifact-input-read:"+nativeArtifactInputStepV1(),mode:"exclusive",elapsedMs:0});await control.yieldContinuation();check();}if(hash.digest("hex")!==input.sha256||protectedArtifactInputStampV1(file.stat())!==before)throw Error("Staged immutable input content changed");});const after=await directory.entry(name);check();if(!after||protectedArtifactInputStampV1(after)!==before)throw Error("Staged immutable input named identity changed");}
  else if(++quiet>=256){quiet=0;await control.publish({resource:"native-artifact-input-read:"+nativeArtifactInputStepV1(),mode:"exclusive",elapsedMs:0});await control.yieldContinuation();check();}
  if(record)files.set(path,before);}});
 if(closed)await visitProtectedArtifactInputDirectoriesV1(root,stamps.keys(),async(path,directory)=>{check();if(protectedArtifactInputStampV1(directory.stat())!==stamps.get(path))throw Error("Complete fresh input directory changed during readback");});
 if(mode==="all")protectedArtifactInputRecordedV1.set(directories,startedAtNs);
}
'''
doc='''/** 📥️ Reads every staged source file back through fresh issued directory lineage without qualifying installed descendants; each directory is walked once from its parent, and a read hashes only the files its mode names (`all` the recording and complete fresh reads, `root` the one issued root, `changed` none but racy ones) and vouches for the rest by their recorded stamps, so the work no longer grows with the number of roots times the number of files. See ./🧮️read-plan/🧬️schema/🔣️.json */\n'''
