old='''for(const path of paths)await withProtectedArtifactInputDirectoryV1(root,path.split("/"),async directory=>{check();directories.set(path,protectedArtifactInputAnchorV1(directory.stat()));});for(const input of batch.files){const path=batch.roots[input.root]!+"/"+input.path,parts=path.split("/"),name=parts.pop()!;await withProtectedArtifactInputDirectoryV1(root,parts,async directory=>{check();const entry=await directory.entry(name);if(!entry||entry.kind!=="file"||entry.nlink!==1n||entry.dev!==root.stat().dev||entry.size!==BigInt(input.bytes))throw Error("Exact current immutable input file required");files.set(path,protectedArtifactInputStampV1(entry));});}'''
new='''await visitProtectedArtifactInputDirectoriesV1(root,paths,async(path,directory)=>{check();directories.set(path,protectedArtifactInputAnchorV1(directory.stat()));});const parents=new Map<string,typeof batch.files[number][]>();for(const input of batch.files){const path=batch.roots[input.root]!+"/"+input.path,parent=path.slice(0,path.lastIndexOf("/"));let group=parents.get(parent);if(!group){group=[];parents.set(parent,group);}group.push(input);}await visitProtectedArtifactInputDirectoriesV1(root,parents.keys(),async(parent,directory)=>{for(const input of parents.get(parent)!){check();const path=batch.roots[input.root]!+"/"+input.path,name=path.slice(path.lastIndexOf("/")+1),entry=await directory.entry(name);if(!entry||entry.kind!=="file"||entry.nlink!==1n||entry.dev!==root.stat().dev||entry.size!==BigInt(input.bytes))throw Error("Exact current immutable input file required");files.set(path,protectedArtifactInputStampV1(entry));}});'''
